import java.util.Scanner;

class Persona {
    String nombre;
    int edad;
    public Persona(String nombre, int edad) {
        this.nombre = nombre;
        this.edad = edad;
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        Persona mayor = null;
        for (int i = 1; i <= N; i++) {
            String nombre = sc.next();
            int edad = sc.nextInt();
            Persona p = new Persona(nombre, edad);
            System.out.println("Persona " + i + ": " + p.nombre + " (" + p.edad + " años)");
            if (mayor == null || p.edad > mayor.edad) mayor = p;
        }
        if (mayor != null) System.out.println("Mayor: " + mayor.nombre + " con " + mayor.edad + " años");
    }
}

