        String expr = sc.hasNext() ? sc.next() : "";
        Stack<Character> pila = new Stack<>();
        boolean ok = true;
        for (int i = 0; i < expr.length(); i++) {
            char c = expr.charAt(i);
            if (c == '(' || c == '[' || c == '{') {
                pila.push(c);
            } else if (c == ')' || c == ']' || c == '}') {
                if (pila.empty()) { ok = false; break; }
                char top = pila.pop();
                if ((c == ')' && top != '(') || (c == ']' && top != '[') || (c == '}' && top != '{')) {
                    ok = false; break;
                }
            }
        }
        if (!pila.empty()) ok = false;
        System.out.println(ok ? "BALANCEADO" : "DESBALANCEADO");
    }
}

